cd "/Users/eilonxtxue/Documents/obsidian/obsidian_bk" && python3 - <<'EOF'
import re, pathlib
pat = re.compile(r'!\[[^\]]*\]\(([^)\n]*)\)')
title=0; hashq=0; nested=[]; angle=0; enc=0
samples=set()
for p in pathlib.Path('.').rglob('*.md'):
    if '.obsidian' in p.parts: continue
    t = p.read_text(encoding='utf-8')
    for m in pat.finditer(t):
        u = m.group(1)
        if u.startswith(('http','<')): 
            angle += u.startswith('<'); continue
        if '"' in u or "'" in u: title+=1; samples.add(('TITLE',u[:70]))
        if '#' in u or '?' in u: hashq+=1; samples.add(('HASH/Q',u[:70]))
        if '%20' in u: enc+=1
        if '(' in u or ')' in u: nested.append(u[:70])
print("带 title 引号的:",title," 含 #/? 的:",hashq," <>包裹:",angle," 已%20:",enc," 路径含括号:",len(nested))
for s in list(samples)[:6]: print("  ",s)
print("\n=== alt 文本非空的本地图片（确认前缀语法）===")
n=0
for p in pathlib.Path('.').rglob('*.md'):
    if '.obsidian' in p.parts: continue
    for m in re.finditer(r'!\[([^\]]+)\]\(([^)h][^)\n]*)\)', p.read_text(encoding='utf-8')):
        if n<8: print("   alt=%r" % m.group(1), "->", m.group(2)[:55])
        n+=1
print("总计:",n)
EOF

