import re, pathlib
pat = re.compile(r'(!\[[^\]]*\]\()([^)\n]+)(\))')
def fix(m):
    u = m.group(2)
    if u.startswith(('http://','https://','<')) or ' ' not in u:
        return m.group(0)
    return m.group(1) + u.replace(' ', '%20') + m.group(3)

total=0; files=0
for p in sorted(pathlib.Path('.').rglob('*.md')):
    if '.obsidian' in p.parts: continue
    t = p.read_text(encoding='utf-8')
    new, n = pat.subn(fix, t)
    if n and new != t:
        files+=1; total+=sum(1 for m in pat.finditer(t)
                             if not m.group(2).startswith(('http','<')) and ' ' in m.group(2))
print(f"将修改 {files} 个文件，共 {total} 处引用")
print("\n--- PrimitiveVLA 这篇的 diff 预览 ---")
p = pathlib.Path('AIReadPaper/10-Papers/VLA/PrimitiveVLA - 可复用动作原语的机器人操控.md')
for line in p.read_text(encoding='utf-8').splitlines():
    if line.startswith('!['):
        print("  -", line)
        print("  +", pat.sub(fix, line))
EOF

