cd "/Users/eilonxtxue/Documents/obsidian/obsidian_bk/AIReadPaper" && python3 - <<'EOF'
import re, pathlib, urllib.parse, unicodedata
pat = re.compile(r'!\[([^\]]*)\]\(([^)\n]*)\)')
nfc_issue=[]; case_issue=[]; svg=[]; huge=[]; alt_pipe=[]; outside=[]
for p in pathlib.Path('.').rglob('*.md'):
    t = re.sub(r'```.*?```','',p.read_text(encoding='utf-8'),flags=re.S)
    for m in pat.finditer(t):
        alt,u = m.group(1), m.group(2).strip()
        if u.startswith('http') or not u: continue
        raw = urllib.parse.unquote(u)
        tgt = p.parent / raw
        # Unicode 规范化差异（macOS NFD vs NFC）
        if unicodedata.normalize('NFC', raw) != raw:
            nfc_issue.append((str(p), u))
        # 大小写：磁盘存在但大小写不同
        if tgt.exists():
            real = tgt.resolve()
            if real.name != tgt.name: case_issue.append((str(p),u))
            sz = real.stat().st_size
            if sz > 5*1024*1024: huge.append((str(p), tgt.name, sz//1024//1024))
            if real.suffix.lower()=='.svg': svg.append((str(p),tgt.name))
        # 引用跳出 AIReadPaper
        if '..' in raw: outside.append((str(p),u))
        if '|' in alt: alt_pipe.append((str(p),alt[:40]))
print("Unicode NFD/NFC 不一致:", len(nfc_issue))
for x in nfc_issue[:5]: print("   ",x)
print("大小写不匹配:", len(case_issue))
print("含 .. 跳出目录:", len(outside))
for x in outside[:5]: print("   ",x)
print("SVG 图片:", len(svg))
for x in svg: print("   ",x)
print("超过 5MB 的图（可能加载慢/超限）:", len(huge))
for x in sorted(huge,key=lambda y:-y[2])[:8]: print(f"    {x[2]}MB  {x[1]}  in {x[0]}")
print("alt 里带 | 宽度前缀:", len(alt_pipe))
EOF

