import re, pathlib, urllib.parse, subprocess
pat = re.compile(r'!\[[^\]]*\]\(([^)\n]*)\)')
seen=set()
for p in pathlib.Path('.').rglob('*.md'):
    t = re.sub(r'```.*?```','',p.read_text(encoding='utf-8'),flags=re.S)
    for m in pat.finditer(t):
        u=m.group(1).strip()
        if u.startswith('http') or not u: continue
        tgt = (p.parent / urllib.parse.unquote(u))
        if tgt.exists(): seen.add(str(tgt.resolve()))
print("唯一被引用的图片文件:", len(seen))
bad=[]
for f in sorted(seen):
    out = subprocess.run(['file','-b',f],capture_output=True,text=True).stdout.strip()
    if not any(k in out for k in ('PNG image','JPEG image','SVG','GIF','WebP','TIFF'):
        bad.append((f,out))
print("非图片/损坏:",len(bad))
for f,o in bad[:10]: print("   ",o,"<-",f.split('/')[-1])
EOF

