import pathlib
from PIL import Image
big=[]
for f in pathlib.Path('.').rglob('*'):
    if f.suffix.lower() in ('.png','.jpg','.jpeg') and f.is_file():
        sz=f.stat().st_size
        if sz > 2*1024*1024:
            try:
                im=Image.open(f); big.append((sz, im.size, im.mode, str(f)))
            except Exception as e: big.append((sz,None,str(e),str(f)))
big.sort(reverse=True)
print(f"{'MB':>6} {'尺寸':>14} {'模式':>6}  文件")
for sz,dim,mode,f in big:
    print(f"{sz/1048576:6.1f} {str(dim):>14} {mode:>6}  {f}")
print("\n合计:",len(big),"个文件", f"{sum(b[0] for b in big)/1048576:.1f} MB")
EOF

