import glob,re
files=sorted(glob.glob("**/*.md",recursive=True))
CJK=re.compile(r"[\u4e00-\u9fff\u3000-\u303f\uff00-\uffef]")
def segs(lines):
    """yield (lineno, mathtext) for inline and display math"""
    infence=False; indisp=False; buf=[]; st=0
    for i,l in enumerate(lines,1):
        s=l.strip()
        if s.startswith("```"):
            infence=not infence; continue
        if infence: continue
        if not indisp and s=="$$":
            indisp=True; buf=[]; st=i; continue
        if indisp:
            if s=="$$":
                indisp=False
                yield (st,"\n".join(buf),"D")
            else: buf.append(l)
            continue
        l2=re.sub(r"`[^`]*`","",l)
        for m in re.finditer(r"\$([^$]+)\$", l2):
            yield (i,m.group(1),"I")
for f in files:
    lines=open(f,encoding="utf-8").read().split("\n")
    for ln,m,kind in segs(lines):
        # strip \text{...} \mathrm{...} \textbf etc contents
        stripped=re.sub(r"\\(?:text|textbf|textit|mathrm|textrm|mbox|hbox)\s*\{[^{}]*\}","",m)
        stripped=re.sub(r"\\(?:text|textbf|textit|mathrm)\s*\{[^{}]*\{[^{}]*\}[^{}]*\}","",stripped)
        hits=CJK.findall(stripped)
        if hits:
            print(f"{f}:{ln}: [CJK-IN-MATH {kind}] chars={\"\".join(sorted(set(hits)))} :: {m[:160]}")
