import glob,re
files=sorted(glob.glob("**/*.md",recursive=True))
def segs(lines):
    infence=False; indisp=False; buf=[]; st=0
    for i,l in enumerate(lines,1):
        s=l.strip()
        if s.startswith("```"): infence=not infence; continue
        if infence: continue
        if not indisp and s=="$$":
            indisp=True; buf=[]; st=i; continue
        if indisp:
            if s=="$$": indisp=False; yield (st,"\n".join(buf),"D")
            else: buf.append(l)
            continue
        l2=re.sub(r"`[^`]*`","",l)
        for m in re.finditer(r"\$\$?([^$]+)\$\$?", l2):
            yield (i,m.group(1),"I")
for f in files:
    lines=open(f,encoding="utf-8").read().split("\n")
    for ln,m,k in segs(lines):
        probs=[]
        # dangling sub/sup: _ or ^ followed by space, end, }, or another _ / ^
        for mm in re.finditer(r"[_^](?=\s|$|[}\)\],])", m):
            probs.append("DANGLING-SUBSUP@"+repr(m[max(0,mm.start()-12):mm.start()+4]))
        # multi-char sub/sup without braces: _ab or ^ab (2+ alnum)
        for mm in re.finditer(r"[_^](?!\{)([A-Za-z0-9]{2,})", m):
            probs.append("UNBRACED-SUBSUP@"+mm.group(0))
        # double subscript x_i_j
        for mm in re.finditer(r"_(?:\{[^{}]*\}|[^\s{}])_", m):
            probs.append("DOUBLE-SUB@"+mm.group(0))
        for mm in re.finditer(r"\^(?:\{[^{}]*\}|[^\s{}])\^", m):
            probs.append("DOUBLE-SUP@"+mm.group(0))
        # brace balance
        b=m.replace("\\{","").replace("\\}","")
        if b.count("{")!=b.count("}"):
            probs.append(f"BRACE-IMBALANCE open={b.count(chr(123))} close={b.count(chr(125))}")
        if probs:
            print(f"{f}:{ln} [{k}] " + "; ".join(sorted(set(probs))))
            print("      >> " + m[:220].replace(chr(10)," / "))
'

