    t=re.sub(r'`[^`\n]*`','',t)
    # $ 平衡
    disp=len(re.findall(r'\$\$',t))
    t2=re.sub(r'\$\$.*?\$\$','',t,flags=re.S)
    sing=len(re.findall(r'(?<!\\)\$',t2))
    if disp%2 or sing%2: issues.append((p,0,'$配对奇数',f'$$={disp} $={sing}'))
    # 空/残缺公式
    for i,l in enumerate(raw.split('\n'),1):
        for m in re.finditer(r'\$\$?([^$\n]*)\$\$?', l):
            c=m.group(1)
            if not c.strip(): issues.append((p,i,'空公式',m.group(0)))
            elif c.count('{')!=c.count('}'): issues.append((p,i,'花括号不平衡',m.group(0)[:50]))
            elif c.count('(')!=c.count(')'): issues.append((p,i,'圆括号不平衡',m.group(0)[:50]))
            elif re.search(r'[_^]\s*$',c): issues.append((p,i,'下标悬空',m.group(0)[:50]))
    # 不支持的命令
    for cmd in [r'\\bm\b', r'\\argmin\b', r'\\argmax\b', r'\\mathbbm\b', r'\\eqref\b', r'\\intertext\b']:
        for m in re.finditer(cmd, raw):
            ln=raw[:m.start()].count('\n')+1
            issues.append((p,ln,'MathJax不支持',m.group(0)))
    # 错误分隔符
    for m in re.finditer(r'\\\(|\\\)|\\\[(?!\d)', raw):
        ln=raw[:m.start()].count('\n')+1
        issues.append((p,ln,'错误分隔符',m.group(0)))
